// The Decision Book's conflict model, narrowed to one move: each side steps a little toward the
// other, and the two steps have to open a shared possibility. The six-response taxonomy stays
// in dm_conflict (pairsWell); here the joint contribution is a required group.
export const rbOneStep = Object.freeze({
  ...listTool({
    id: 'rb_one_step',
    name: 'The One-Step-Closer Rule',
    when: 'Two sides are stuck defending positions rather than exploring a possible agreement.',
    failureModes: [
      'Requiring all movement from one side',
      'Confusing reciprocal exploration with surrender',
      'Promising agreement without the other party'
    ],
    steps: [
      step('frame', 'Name the situation', 'Describe a current, concrete example and what you want to understand.'),
      step('mine', 'My step', 'What small movement away from your fixed position could you offer?'),
      step('theirs', 'Their step', 'What small movement could the other side offer, without you promising it for them?'),
      step('shared', 'What the two steps open', 'What shared possibility would those two movements reveal? Without one there is nothing to propose yet.'),
      step('review', 'Set a small test', 'What is one proportionate next action, and what observation would make you reconsider it?')
    ],
    exercise: 'Propose one reciprocal exploratory step in a low-stakes disagreement.',
    pairsWell: ['dm_conflict', 'rb_wiio'],
    chart: {
      layout: 'rows',
      groups: [
        { id: 'mine', label: 'My step toward them', prompt: 'A small movement you can offer' },
        { id: 'theirs', label: 'Their step toward me', prompt: 'A small movement they might offer' },
        { id: 'shared', label: 'What the two steps open up', prompt: 'The joint contribution: a possibility neither side had alone' }
      ],
      entry: 'One movement, or the shared possibility the two steps open',
      perGroup: 3,
      minEntries: 3,
      minGroups: 3
    }
  }),
  variantOf: 'dm_conflict'
});

